// Filter applies the CheckResultWhereInput filter on the CheckResultQuery builder.
func (i *CheckResultWhereInput) Filter(q *CheckResultQuery) (*CheckResultQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyCheckResultWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

