// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *DiscussionWhereInput) AddPredicates(predicates ...predicate.Discussion) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the DiscussionWhereInput filter on the DiscussionQuery builder.
func (i *DiscussionWhereInput) Filter(q *DiscussionQuery) (*DiscussionQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyDiscussionWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

