// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *FindingWhereInput) AddPredicates(predicates ...predicate.Finding) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the FindingWhereInput filter on the FindingQuery builder.
func (i *FindingWhereInput) Filter(q *FindingQuery) (*FindingQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyFindingWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

