// AddPredicates adds custom predicates to the where input to be used during the filtering phase.
func (i *PlatformWhereInput) AddPredicates(predicates ...predicate.Platform) {
	i.Predicates = append(i.Predicates, predicates...)
}

// Filter applies the PlatformWhereInput filter on the PlatformQuery builder.
func (i *PlatformWhereInput) Filter(q *PlatformQuery) (*PlatformQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyPlatformWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

