// Filter applies the ReviewWhereInput filter on the ReviewQuery builder.
func (i *ReviewWhereInput) Filter(q *ReviewQuery) (*ReviewQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyReviewWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

